import{_ as o,a0 as p,w as i,s as d,I as s,x as t,a1 as a,A as n,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const Q=JSON.parse('{"title":"如何在 Linux 系統中創建一個雲端加密文件系統 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 系統中創建一個雲端加密文件系統 | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 系統中創建一個雲端加密文件系統 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 系統中創建一個雲端加密文件系統 | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20140910 How to create a cloud-based encrypted file system on Linux","title":"如何在 Linux 系統中創建一個雲端加密文件系統","tag":"201412","desc":""},"relativePath":"201412/20140910 How to create a cloud-based encrypted file system on Linux.md","filePath":"[post].md"}'),u={name:"201412/20140910 How to create a cloud-based encrypted file system on Linux.md"};function m(f,e,S,L,b,x){const l=p("Link");return i(),d("div",null,[e[31]||(e[31]=s("h1",{id:"如何在-linux-系統中創建一個雲端加密文件系統",tabindex:"-1"},[t("如何在 Linux 系統中創建一個雲端加密文件系統 "),s("a",{class:"header-anchor",href:"#如何在-linux-系統中創建一個雲端加密文件系統","aria-label":"Permalink to “如何在 Linux 系統中創建一個雲端加密文件系統”"},"​")],-1)),s("p",null,[a(l,{href:"http://aws.amazon.com/s3"},{default:n(()=>[...e[0]||(e[0]=[t("Amazon S3",-1)])]),_:1}),e[2]||(e[2]=t(" 和 ",-1)),a(l,{href:"http://code.google.com/apis/storage/"},{default:n(()=>[...e[1]||(e[1]=[t("Google Cloud Storage",-1)])]),_:1}),e[3]||(e[3]=t(" 之類的商業雲存儲服務以能承受的價格提供了高可用性、可擴展、無限容量的對象存儲服務。為了加速這些雲產品的廣泛採用，這些提供商為他們的產品通過明確的 API 和 SDK 培養了一個良好的開發者生態系統。而基於雲的文件系統便是這些活躍的開發者社區中的典型產品，已經有了好幾個開源的實現。",-1))]),s("p",null,[a(l,{href:"https://bitbucket.org/nikratio/s3ql/"},{default:n(()=>[...e[4]||(e[4]=[t("S3QL",-1)])]),_:1}),e[5]||(e[5]=t(" 便是最流行的開源雲端文件系統之一。它是一個基於 FUSE 的文件系統，提供了好幾個商業或開源的雲存儲後端，比如 Amazon S3、Google Cloud Storage、Rackspace CloudFiles，還有 OpenStack。作為一個功能完整的文件系統，S3QL 擁有不少強大的功能：最大 2T 的文件大小、壓縮、UNIX 屬性、加密、基於寫入時複製的快照、不可變樹、重複數據刪除，以及軟、硬鏈接支持等等。寫入 S3QL 文件系統任何數據都將首先被本地壓縮、加密，之後才會傳輸到雲後端。當你試圖從 S3QL 文件系統中取出內容的時候，如果它們不在本地緩存中，相應的對象會從雲端下載回來，然後再即時地解密、解壓縮。",-1))]),e[32]||(e[32]=s("p",null,"需要明確的是，S3QL 的確也有它的限制。比如，你不能把同一個 S3FS 文件系統在幾個不同的電腦上同時掛載，只能有一台電腦同時訪問它。另外，ACL（訪問控制列表）也並沒有被支持。",-1)),e[33]||(e[33]=s("p",null,"在這篇教程中，我將會描述“如何基於 Amazon S3 用 S3QL 配置一個加密文件系統”。作為一個使用範例，我還會説明如何在掛載的 S3QL 文件系統上運行 rsync 備份工具。",-1)),e[34]||(e[34]=s("h3",{id:"準備工作",tabindex:"-1"},[t("準備工作 "),s("a",{class:"header-anchor",href:"#準備工作","aria-label":"Permalink to “準備工作”"},"​")],-1)),s("p",null,[e[7]||(e[7]=t("本教程首先需要你創建一個 ",-1)),a(l,{href:"http://aws.amazon.com/"},{default:n(()=>[...e[6]||(e[6]=[t("Amazon AWS 帳號",-1)])]),_:1}),e[8]||(e[8]=t("（註冊是免費的，但是需要一張有效的信用卡）。",-1))]),s("p",null,[e[10]||(e[10]=t("然後 ",-1)),a(l,{href:"http://aws.amazon.com/"},{default:n(()=>[...e[9]||(e[9]=[t("創建一個 AWS access key",-1)])]),_:1}),e[11]||(e[11]=t("（access key ID 和 secret access key），S3QL 使用這些信息來訪問你的 AWS 帳號。",-1))]),e[35]||(e[35]=r(`<p>之後通過 AWS 管理面板訪問 AWS S3，併為 S3QL 創建一個新的空 bucket。</p><p><img src="https://farm4.staticflickr.com/3841/15170673701_7d0660e11f_c.jpg" alt=""></p><p>為最佳性能考慮，請選擇一個地理上距離你最近的區域。</p><p><img src="https://farm4.staticflickr.com/3902/15150663516_4928d757fc_b.jpg" alt=""></p><h3 id="在-linux-上安裝-s3ql" tabindex="-1">在 Linux 上安裝 S3QL <a class="header-anchor" href="#在-linux-上安裝-s3ql" aria-label="Permalink to “在 Linux 上安裝 S3QL”">​</a></h3><p>在大多數 Linux 發行版中都有預先編譯好的 S3QL 軟件包。</p><h4 id="對於-debian、ubuntu-或-linux-mint" tabindex="-1">對於 Debian、Ubuntu 或 Linux Mint：#### <a class="header-anchor" href="#對於-debian、ubuntu-或-linux-mint" aria-label="Permalink to “對於 Debian、Ubuntu 或 Linux Mint：####”">​</a></h4><pre><code>$ sudo apt-get install s3ql
</code></pre><h4 id="對於-fedora" tabindex="-1">對於 Fedora：#### <a class="header-anchor" href="#對於-fedora" aria-label="Permalink to “對於 Fedora：####”">​</a></h4><pre><code>$ sudo yum install s3ql
</code></pre>`,10)),s("p",null,[e[13]||(e[13]=t("對於 Arch Linux，使用 ",-1)),a(l,{href:"https://aur.archlinux.org/packages/s3ql/"},{default:n(()=>[...e[12]||(e[12]=[t("AUR",-1)])]),_:1}),e[14]||(e[14]=t("。",-1))]),e[36]||(e[36]=r(`<h3 id="首次配置-s3ql" tabindex="-1">首次配置 S3QL <a class="header-anchor" href="#首次配置-s3ql" aria-label="Permalink to “首次配置 S3QL”">​</a></h3><p>在 ~/.s3ql 目錄中創建 autoinfo2 文件，它是 S3QL 的一個默認的配置文件。這個文件裏的信息包括必須的 AWS access key，S3 bucket 名，以及加密口令。這個加密口令將被用來加密一個隨機生成的主密鑰，而主密鑰將被用來實際地加密 S3QL 文件系統數據。</p><pre><code>$ mkdir ~/.s3ql
$ vi ~/.s3ql/authinfo2
</code></pre><hr><pre><code>[s3]
storage-url: s3://[bucket-name]
backend-login: [your-access-key-id]
backend-password: [your-secret-access-key]
fs-passphrase: [your-encryption-passphrase]
</code></pre><p>指定的 AWS S3 bucket 需要預先通過 AWS 管理面板來創建。</p><p>為了安全起見，讓 authinfo2 文件僅對你可訪問。</p><pre><code>$ chmod 600 ~/.s3ql/authinfo2
</code></pre><h3 id="創建-s3ql-文件系統" tabindex="-1">創建 S3QL 文件系統 <a class="header-anchor" href="#創建-s3ql-文件系統" aria-label="Permalink to “創建 S3QL 文件系統”">​</a></h3><p>現在你已經準備好可以在 AWS S3 上創建一個 S3QL 文件系統了。</p><p>使用 mkfs.s3ql 工具來創建一個新的 S3QL 文件系統。這個命令中的 bucket 名應該與 authinfo2 文件中所指定的相符。使用“--ssl”參數將強制使用 SSL 連接到後端存儲服務器。默認情況下，mkfs.s3ql 命令會在 S3QL 文件系統中啓用壓縮和加密。</p><pre><code>$ mkfs.s3ql s3://[bucket-name] --ssl
</code></pre><p>你會被要求輸入一個加密口令。請輸入你在 ~/.s3ql/autoinfo2 中通過“fs-passphrase”指定的那個口令。</p><p>如果一個新文件系統被成功創建，你將會看到這樣的輸出：</p><p><img src="https://farm6.staticflickr.com/5582/14988587230_e182ca3abd_z.jpg" alt=""></p><h3 id="掛載-s3ql-文件系統" tabindex="-1">掛載 S3QL 文件系統 <a class="header-anchor" href="#掛載-s3ql-文件系統" aria-label="Permalink to “掛載 S3QL 文件系統”">​</a></h3><p>當你創建了一個 S3QL 文件系統之後，下一步便是要掛載它。</p><p>首先創建一個本地的掛載點，然後使用 mount.s3ql 命令來掛載 S3QL 文件系統。</p><pre><code>$ mkdir ~/mnt_s3ql
$ mount.s3ql s3://[bucket-name] ~/mnt_s3ql
</code></pre><p>掛載一個 S3QL 文件系統不需要特權用户，只要確定你對該掛載點有寫權限即可。</p><p>視情況，你可以使用“--compress”參數來指定一個壓縮算法（如 lzma、bzip2、zlib）。在不指定的情況下，lzma 將被默認使用。注意如果你指定了一個自定義的壓縮算法，它將只會應用到新創建的數據對象上，並不會影響已經存在的數據對象。</p><pre><code>$ mount.s3ql --compress bzip2 s3://[bucket-name] ~/mnt_s3ql
</code></pre><p>因為性能原因，S3QL 文件系統維護了一份本地文件緩存，裏面包括了最近訪問的（部分或全部的）文件。你可以通過“--cachesize”和“--max-cache-entries”選項來自定義文件緩存的大小。</p><p>如果想要除你以外的用户訪問一個已掛載的 S3QL 文件系統，請使用“--allow-other”選項。</p><p>如果你想通過 NFS 導出已掛載的 S3QL 文件系統到其他機器，請使用“--nfs”選項。</p><p>運行 mount.s3ql 之後，檢查 S3QL 文件系統是否被成功掛載了：</p><pre><code>$ df ~/mnt_s3ql
$ mount | grep s3ql
</code></pre><p><img src="https://farm4.staticflickr.com/3863/15174861482_27a842da3e_z.jpg" alt=""></p><h3 id="卸載-s3ql-文件系統" tabindex="-1">卸載 S3QL 文件系統 <a class="header-anchor" href="#卸載-s3ql-文件系統" aria-label="Permalink to “卸載 S3QL 文件系統”">​</a></h3><p>想要安全地卸載一個（可能含有未提交數據的）S3QL 文件系統，請使用 umount.s3ql 命令。它將會等待所有數據（包括本地文件系統緩存中的部分）成功傳輸到後端服務器。取決於等待寫的數據的多少，這個過程可能需要一些時間。</p><pre><code>$ umount.s3ql ~/mnt_s3ql
</code></pre><h3 id="查看-s3ql-文件系統統計信息及修復-s3ql-文件系統" tabindex="-1">查看 S3QL 文件系統統計信息及修復 S3QL 文件系統 <a class="header-anchor" href="#查看-s3ql-文件系統統計信息及修復-s3ql-文件系統" aria-label="Permalink to “查看 S3QL 文件系統統計信息及修復 S3QL 文件系統”">​</a></h3><p>若要查看 S3QL 文件系統統計信息，你可以使用 s3qlstat 命令，它將會顯示諸如總的數據、元數據大小、重複文件刪除率和壓縮率等信息。</p><pre><code>$ s3qlstat ~/mnt_s3ql
</code></pre><p><img src="https://farm6.staticflickr.com/5559/15184926905_4815e5827a_z.jpg" alt=""></p><p>你可以使用 fsck.s3ql 命令來檢查和修復 S3QL 文件系統。與 fsck 命令類似，待檢查的文件系統必須首先被卸載。</p><pre><code>$ fsck.s3ql s3://[bucket-name]
</code></pre><h3 id="s3ql-使用案例-rsync-備份" tabindex="-1">S3QL 使用案例：Rsync 備份 <a class="header-anchor" href="#s3ql-使用案例-rsync-備份" aria-label="Permalink to “S3QL 使用案例：Rsync 備份”">​</a></h3><p>讓我用一個流行的使用案例來結束這篇教程：本地文件系統備份。為此，我推薦使用 rsync 增量備份工具，特別是因為 S3QL 提供了一個 rsync 的封裝腳本（/usr/lib/s3ql/pcp.py）。這個腳本允許你使用多個 rsync 進程遞歸地複製目錄樹到 S3QL 目標。</p><pre><code>$ /usr/lib/s3ql/pcp.py -h
</code></pre><p><img src="https://farm4.staticflickr.com/3873/14998096829_d3a64749d0_z.jpg" alt=""></p><p>下面這個命令將會使用 4 個併發的 rsync 連接來備份 ~/Documents 裏的所有內容到一個 S3QL 文件系統。</p><pre><code> $ /usr/lib/s3ql/pcp.py -a --quiet --processes=4 ~/Documents ~/mnt_s3ql
</code></pre><p>這些文件將首先被複制到本地文件緩存中，然後在後台再逐步地同步到後端服務器。</p>`,44)),s("p",null,[e[16]||(e[16]=t("若想了解與 S3QL 有關的更多信息，如自動掛載、快照、不可變樹，我強烈推薦閲讀 ",-1)),a(l,{href:"http://www.rath.org/s3ql-docs/"},{default:n(()=>[...e[15]||(e[15]=[t("官方用户指南",-1)])]),_:1}),e[17]||(e[17]=t("。歡迎告訴我你對 S3QL 怎麼看，以及你對任何其他工具的使用經驗。",-1))]),e[37]||(e[37]=s("hr",null,null,-1)),s("p",null,[e[19]||(e[19]=t("via: ",-1)),a(l,{href:"http://xmodulo.com/2014/09/create-cloud-based-encrypted-file-system-linux.html"},{default:n(()=>[...e[18]||(e[18]=[t("http://xmodulo.com/2014/09/create-cloud-based-encrypted-file-system-linux.html",-1)])]),_:1})]),s("p",null,[e[23]||(e[23]=t("作者：",-1)),a(l,{href:"http://xmodulo.com/author/nanni"},{default:n(()=>[...e[20]||(e[20]=[t("Dan Nanni",-1)])]),_:1}),e[24]||(e[24]=t(" 譯者：",-1)),a(l,{href:"https://github.com/felixonmars"},{default:n(()=>[...e[21]||(e[21]=[t("felixonmars",-1)])]),_:1}),e[25]||(e[25]=t(" 校對：",-1)),a(l,{href:"https://github.com/wxy"},{default:n(()=>[...e[22]||(e[22]=[t("wxy",-1)])]),_:1})]),s("p",null,[e[28]||(e[28]=t("本文由 ",-1)),a(l,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[26]||(e[26]=[t("LCTT",-1)])]),_:1}),e[29]||(e[29]=t(" 原創翻譯，",-1)),a(l,{href:"http://linux.cn/"},{default:n(()=>[...e[27]||(e[27]=[t("Linux中國",-1)])]),_:1}),e[30]||(e[30]=t(" 榮譽推出",-1))])])}const c=o(u,[["render",m]]);export{Q as __pageData,c as default};
